import DailyModels
import Testing

@testable import FeatureHome

/// Results of react-grid-layout 2.3.0 itself (the version the web grid uses),
/// produced with its `verticalCompactor`, `moveElement` and `withLayoutItem` on
/// pseudo-random layouts, the same calls `GridLayout`'s `onDragStop` and
/// `onResize` make. Regenerate with Node from `react-grid-layout/dist/core.mjs`
/// if the web upgrades the library.
@Suite struct ReactGridLayoutParityTests {
  enum Operation: Equatable {
    case compact
    case move(ModuleID, Int, Int)
    case resize(ModuleID, Int, Int)
  }

  struct Case {
    let op: Operation
    let input: [PanelPlacement]
    let expected: [PanelPlacement]
  }

  @Test func matchesReactGridLayout() throws {
    #expect(Self.rows.count == 300)
    for (index, row) in Self.rows.enumerated() {
      let example = try Self.parse(row)
      let result: [PanelPlacement]
      switch example.op {
      case .compact: result = DashboardLayoutEngine.compact(example.input)
      case .move(let id, let x, let y): result = DashboardLayoutEngine.move(example.input, id: id, x: x, y: y)
      case .resize(let id, let w, let h): result = DashboardLayoutEngine.resize(example.input, id: id, w: w, h: h)
      }
      #expect(result == example.expected, "case \(index): \(row)")
    }
  }

  struct BadRow: Error { let row: String }

  /// `op|placements|placements`, op = `compact`, `move <id> <x> <y>` or
  /// `resize <id> <w> <h>`, placements = `<id> <x> <y> <w> <h>;…`.
  static func parse(_ row: String) throws -> Case {
    let parts = row.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
    guard parts.count == 3 else { throw BadRow(row: row) }
    let opWords = parts[0].split(separator: " ").map(String.init)
    let op: Operation
    switch opWords.first {
    case "compact": op = .compact
    case "move":
      guard opWords.count == 4, let x = Int(opWords[2]), let y = Int(opWords[3]) else { throw BadRow(row: row) }
      op = .move(ModuleID(rawValue: opWords[1]), x, y)
    case "resize":
      guard opWords.count == 4, let w = Int(opWords[2]), let h = Int(opWords[3]) else { throw BadRow(row: row) }
      op = .resize(ModuleID(rawValue: opWords[1]), w, h)
    default: throw BadRow(row: row)
    }
    return Case(op: op, input: try placements(parts[1], row: row), expected: try placements(parts[2], row: row))
  }

  static func placements(_ text: String, row: String) throws -> [PanelPlacement] {
    try text.split(separator: ";").map { item in
      let words = item.split(separator: " ").map(String.init)
      guard words.count == 5, let x = Int(words[1]), let y = Int(words[2]), let w = Int(words[3]),
        let h = Int(words[4])
      else { throw BadRow(row: row) }
      return PanelPlacement(i: ModuleID(rawValue: words[0]), x: x, y: y, w: w, h: h)
    }
  }

